using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip to prove it works
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
var person = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Round-tripped: {person}");

// 2) Probe without throwing — TryGetTypeInfo returns false when
//    the resolver doesn't know about the requested type.
//    Use a source-gen-only resolver so it purposely has no metadata for Person.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new LimitedResolver()
};

if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"Found metadata: {info!.Type.Name}");
else
    Console.WriteLine("No metadata for Person — and no exception thrown!");

// --- helpers ---

record Person(string Name, int Age);

// A resolver that resolves nothing, simulating "type not available".
sealed class LimitedResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

